using System.Net.Http.Headers;
using System.Text;
using System.Text.Json;
using Microsoft.EntityFrameworkCore;
using MKSANCrud.Data;
using MKSANCrud.Models;
using MKSANCrud.Services.Clinica;
namespace MKSANCrud.Services.Psicologia;

// Adaptador administrativo FHIR R4. Não exporta respostas, evolução, testes ou chaves.
public sealed class FhirPsicologiaService(MKSANContext db,IHttpClientFactory clients,IConfiguration config,IClinicaClock clock)
{
 public bool Habilitado=>config.GetValue("PepIntegration:Fhir:Enabled",false);
 public bool Configurado=>Endpoint()!=null&&!string.IsNullOrWhiteSpace(config["PepIntegration:Fhir:BearerToken"])&&Uri.TryCreate(config["PepIntegration:Fhir:IdentifierSystem"],UriKind.Absolute,out _);
 Uri? Endpoint()=>Uri.TryCreate(config["PepIntegration:Fhir:BaseUrl"]?.TrimEnd('/')+"/",UriKind.Absolute,out var u)&&u.Scheme=="https"&&string.IsNullOrEmpty(u.UserInfo)&&string.IsNullOrEmpty(u.Query)&&string.IsNullOrEmpty(u.Fragment)?u:null;
 string IdentifierSystem=>config["PepIntegration:Fhir:IdentifierSystem"]!;
 HttpRequestMessage Request(HttpMethod method,string path){var req=new HttpRequestMessage(method,new Uri(Endpoint()!,path));req.Headers.Authorization=new AuthenticationHeaderValue("Bearer",config["PepIntegration:Fhir:BearerToken"]);req.Headers.Accept.Add(new("application/fhir+json"));return req;}
 static async Task<JsonDocument> ReadAsync(HttpResponseMessage response,CancellationToken ct){using var timeout=CancellationTokenSource.CreateLinkedTokenSource(ct);timeout.CancelAfter(TimeSpan.FromSeconds(15));ct=timeout.Token;if(response.Content.Headers.ContentLength>524288)throw new InvalidDataException();await using var stream=await response.Content.ReadAsStreamAsync(ct);using var bounded=new MemoryStream();var buf=new byte[8192];int n;while((n=await stream.ReadAsync(buf,ct))>0){if(bounded.Length+n>524288)throw new InvalidDataException();bounded.Write(buf,0,n);}return JsonDocument.Parse(bounded.ToArray());}
 public async Task<string> TestarAsync(CancellationToken ct){if(!Habilitado||!Configurado)return "Configure e habilite o adaptador FHIR no servidor.";try{using var req=Request(HttpMethod.Get,"metadata");using var resp=await clients.CreateClient("CallMedPEP").SendAsync(req,HttpCompletionOption.ResponseHeadersRead,ct);if(!resp.IsSuccessStatusCode)return $"O servidor FHIR respondeu HTTP {(int)resp.StatusCode}. Confira as permissões com o fornecedor.";using var doc=await ReadAsync(resp,ct);var e=doc.RootElement;if(e.GetProperty("resourceType").GetString()!="CapabilityStatement"||e.GetProperty("fhirVersion").GetString()!="4.0.1")return "O fornecedor deve disponibilizar FHIR R4 (4.0.1).";var rest=e.GetProperty("rest").EnumerateArray().Where(x=>x.GetProperty("mode").GetString()=="server").ToArray();if(!rest.Any(x=>x.TryGetProperty("interaction",out var a)&&a.EnumerateArray().Any(y=>y.GetProperty("code").GetString()=="transaction")))return "O fornecedor não anuncia transações FHIR. Solicite a habilitação.";foreach(var type in new[]{"Patient","Practitioner","Appointment"})if(!rest.Any(x=>x.TryGetProperty("resource",out var a)&&a.EnumerateArray().Any(y=>y.GetProperty("type").GetString()==type&&y.TryGetProperty("conditionalUpdate",out var v)&&v.ValueKind==JsonValueKind.True)))return "O fornecedor precisa aceitar atualização condicional de "+type+".";return "Conexão e capacidades FHIR R4 verificadas. Homologue com dados de teste antes de habilitar em produção.";}catch(Exception e)when(e is HttpRequestException or TaskCanceledException or JsonException or KeyNotFoundException or InvalidDataException or InvalidOperationException){if(ct.IsCancellationRequested)throw;return "Não foi possível validar o servidor FHIR. Confira o endereço, o token e a compatibilidade com o fornecedor.";}}
 public async Task<string?> BundleAsync(int id,CancellationToken ct){
  var c=await db.Consultas.AsNoTracking().Include(x=>x.Paciente).Include(x=>x.Medico).SingleOrDefaultAsync(x=>x.Id==id,ct);if(c?.Paciente==null||c.Medico==null)return null;
  var duration=await db.Jornadas.Where(x=>x.ConsultaId==id).Select(x=>(int?)x.Duracao).SingleOrDefaultAsync(ct)??c.DuracaoMinutos;
  var start=clock.ConverterParaUtc(c.Data.Date.Add(TimeSpan.Parse(c.Horario)));string Identifier(string type,int n)=>IdentifierSystem+":"+type+"|"+n;string Url(string type,int n)=>type+"?identifier="+Uri.EscapeDataString(Identifier(type,n));
  object Iden(string type,int n)=>new{system=IdentifierSystem+":"+type,value=n.ToString()};
  object Entry(string type,int n,object resource)=>new{resource,request=new{method="PUT",url=Url(type,n)}};
  var patient=new{resourceType="Patient",identifier=new[]{Iden("Patient",c.PacienteId)},active=c.Paciente.Ativo,name=new[]{new{text=c.Paciente.Nome}},birthDate=c.Paciente.DataNascimento?.ToString("yyyy-MM-dd")};
  var professional=FhirPractitioner.Criar(c.Medico, IdentifierSystem);
  var appt=new{resourceType="Appointment",identifier=new[]{Iden("Appointment",id)},status=c.Status switch{ConsultaStatus.Cancelada=>"cancelled",ConsultaStatus.Realizada=>"fulfilled",ConsultaStatus.Ausente=>"noshow",ConsultaStatus.Pendente=>"pending",_=>"booked"},start=start.ToString("o"),end=start.AddMinutes(duration).ToString("o"),participant=new[]{new{actor=new{reference=Url("Patient",c.PacienteId)},status="accepted"},new{actor=new{reference=Url("Practitioner",c.MedicoId)},status="accepted"}}};
  return JsonSerializer.Serialize(new{resourceType="Bundle",type="transaction",entry=new[]{Entry("Patient",c.PacienteId,patient),Entry("Practitioner",c.MedicoId,professional),Entry("Appointment",id,appt)}},new JsonSerializerOptions{DefaultIgnoreCondition=System.Text.Json.Serialization.JsonIgnoreCondition.WhenWritingNull});
 }
 public async Task<bool> EnviarAsync(int id,CancellationToken ct){if(!Habilitado||!Configurado)return false;var bundle=await BundleAsync(id,ct);if(bundle==null)return false;try{using var req=Request(HttpMethod.Post,"");req.Content=new StringContent(bundle,Encoding.UTF8,"application/fhir+json");using var resp=await clients.CreateClient("CallMedPEP").SendAsync(req,HttpCompletionOption.ResponseHeadersRead,ct);if(!resp.IsSuccessStatusCode)return false;using var json=await ReadAsync(resp,ct);var root=json.RootElement;if(root.GetProperty("resourceType").GetString()!="Bundle"||root.GetProperty("type").GetString()!="transaction-response")return false;var entries=root.GetProperty("entry").EnumerateArray().ToArray();return entries.Length==3&&entries.All(e=>{var s=e.GetProperty("response").GetProperty("status").GetString();return s?.Length>=3&&int.TryParse(s[..3],out var code)&&code is >=200 and <300;});}catch(Exception e)when(e is HttpRequestException or TaskCanceledException or JsonException or KeyNotFoundException or InvalidDataException or InvalidOperationException){if(ct.IsCancellationRequested)throw;return false;}}
 public async Task<int> ProcessarAsync(CancellationToken ct){if(!Habilitado||!Configurado)return 0;var rows=await db.PepEventos.Where(x=>x.FhirEntregueEm==null&&x.FhirTentativas<10&&(x.FhirTentarEm==null||x.FhirTentarEm<=DateTime.UtcNow)).OrderBy(x=>x.CriadoEm).Take(20).ToListAsync(ct);var n=0;foreach(var g in rows.GroupBy(x=>x.ConsultaId)){foreach(var e in g){e.FhirTentativas++;e.FhirTentarEm=DateTime.UtcNow.AddMinutes(Math.Min(360,Math.Pow(2,e.FhirTentativas)));}await db.SaveChangesAsync(ct);var ok=await EnviarAsync(g.Key,ct);if(ok){foreach(var e in g)e.FhirEntregueEm=DateTime.UtcNow;n++;}db.AuditoriaEventos.Add(new(){Acao=ok?"Exportação administrativa FHIR concluída":"Exportação administrativa FHIR pendente",Entidade="Consulta",EntidadeId=g.Key.ToString(),CriadoEm=DateTime.UtcNow});await db.SaveChangesAsync(ct);}return n;}
}
